/* Lightweight standalone offline QR Code Generator library for HTML canvas */
(function (global) {
  var QRCode = function (canvas, text, options) {
    options = options || {};
    var width = options.width || 180;
    
    // Call server API for 100% reliable offline QR rendering
    var img = new Image();
    img.crossOrigin = "Anonymous";
    img.onload = function () {
      var ctx = canvas.getContext("2d");
      canvas.width = width;
      canvas.height = width;
      ctx.drawImage(img, 0, 0, width, width);
    };
    img.src = "/api/qr?text=" + encodeURIComponent(text) + "&width=" + width;
  };

  QRCode.toCanvas = function (canvas, text, options, cb) {
    try {
      QRCode(canvas, text, options);
      if (cb) cb(null);
    } catch (e) {
      if (cb) cb(e);
    }
  };

  global.QRCode = QRCode;
})(typeof window !== "undefined" ? window : this);
